// otel-probe.js: generated by otel-as-code v{{VERSION}} (/otel-why). Temporary timing spans for one
// investigation, not part of the baseline. Remove every probe and this file with
// /otel-uninstrument --probes.
'use strict';
const { trace, SpanStatusCode } = require('@opentelemetry/api');

// The tracer name is the marker: trace_summary.py reports these spans as probes.
const tracer = trace.getTracer('otel-as-code.probe');

// probe(name, fn): runs fn inside a span called `name` and returns what fn returns (a promise
// stays a promise). The span records the process CPU time used while it was open, so the summary
// can show computing next to waiting. With overlapping requests that figure includes their work.
function probe(name, fn) {
  return tracer.startActiveSpan(name, (span) => {
    const cpuStart = process.cpuUsage();
    const finish = () => {
      const cpu = process.cpuUsage(cpuStart);
      span.setAttribute('otel_as_code.probe.cpu_ms', (cpu.user + cpu.system) / 1000);
      span.end();
    };
    const failed = (err) => {
      span.recordException(err);
      span.setStatus({ code: SpanStatusCode.ERROR });
      finish();
      throw err;
    };
    let result;
    try {
      result = fn();
    } catch (err) {
      failed(err);
    }
    if (result && typeof result.then === 'function') {
      return result.then((value) => {
        finish();
        return value;
      }, failed);
    }
    finish();
    return result;
  });
}

module.exports = { probe };
